import {journalArticles,socialEntries,highlightCollections} from './journal-data.mjs';

export function createJournalUI({esc,btn,crumb}){
  const published=journalArticles.filter(a=>a.status==='published');
  const allStories=socialEntries.filter(e=>e.kind==='story'&&e.status!=='draft');
  const allReels=socialEntries.filter(e=>e.kind==='reel'&&e.status==='published'&&!e.archived);
  const cleanText=v=>String(v??'').toLocaleLowerCase('ru').replace(/ё/g,'е');
  const href=path=>'#'+path;
  const date=value=>{const [y,m,d]=String(value||'').split('-');return d&&m&&y?`${Number(d)} ${['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'][Number(m)-1]} ${y}`:'';};
  const kindLabel=kind=>kind==='news'?'Новости':'Полезное';
  const image=(media,{className='',eager=false}={})=>`<img class="${className}" src="${esc(media.type==='video'?media.poster:media.src)}" alt="${esc(media.alt||'Иллюстрация материала')}" loading="${eager?'eager':'lazy'}" decoding="async" width="1254" height="1254">`;
  const demoBadge=(text='Демо')=>`<span class="journal-demo-badge">${esc(text)}</span>`;
  const notice=(news=false)=>`<p class="journal-demo-note">${news?'Демонстрационные редакционные примеры. Публикации не сообщают о реальных событиях компании.':'Демонстрационная редакционная коллекция. Изображения — AI-визуализации, видео — иллюстративные материалы.'}</p>`;
  const arrow='<span aria-hidden="true">↗</span>';
  function nav(active){const entries=[['/journal','Обзор'],['/journal/useful','Полезное'],['/journal/news','Новости'],['/stories','Истории'],['/reels','Reels']];return `<nav class="journal-nav" aria-label="Разделы журнала">${entries.map(([path,title])=>`<a href="${href(path)}" ${active===path?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;}
  function heading(eyebrow,title,intro,extra=''){return `<header class="journal-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${esc(intro)}</p>${extra}</header>`;}
  function articleCard(a,{featured=false}={}){return `<a class="journal-card ${featured?'journal-card-featured':''}" href="#/journal/article/${esc(a.id)}"><div class="journal-card-image">${image(a.cover)}${a.demo?demoBadge(a.kind==='news'?'Редакционный пример':'Демо журнала'):''}</div><div class="journal-card-copy"><div class="journal-meta"><span>${esc(a.topic)}</span><span>${a.readMinutes} мин</span></div><h3>${esc(a.title)}</h3><p>${esc(a.intro)}</p><div class="journal-card-bottom"><time datetime="${esc(a.publishDate)}">${date(a.publishDate)}</time>${arrow}</div></div></a>`;}
  function articleGrid(list){return `<div class="journal-grid">${list.map(a=>articleCard(a)).join('')}</div>`;}
  function storyCard(entry,{collection='',compact=false}={}){return `<a class="story-card ${compact?'story-card-compact':''}" href="#/stories/${esc(entry.id)}${collection?'?collection='+encodeURIComponent(collection):''}"><div class="story-card-image">${image(entry.media)}<span class="story-card-type">${entry.media.type==='video'?'Видео · без звука':'Фотоиллюстрация'}</span>${entry.demo?demoBadge():''}<div class="story-card-caption"><span>${esc(entry.topic)}</span><h3>${esc(entry.title)}</h3></div></div><div class="story-card-bottom"><time datetime="${esc(entry.publishDate)}">${date(entry.publishDate)}</time>${arrow}</div></a>`;}
  function storyTabs(mode){return `<nav class="story-tabs" aria-label="Публикации историй">${[['active','/stories','Активные'],['archive','/stories/archive','Архив'],['highlights','/stories/highlights','Подборки']].map(([key,path,title])=>`<a href="${href(path)}" ${mode===key?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;}
  function related(item){return item.related?`<aside class="journal-related"><div><span class="eyebrow">ОТ ИДЕИ К ВЫБОРУ</span><h2>${esc(item.related.label)}</h2>${item.related.intro?`<p>${esc(item.related.intro)}</p>`:''}</div>${btn(esc(item.related.label),href(item.related.path),'clear')}</aside>`:'';}
  function empty(title,text,path,label){return `<section class="journal-empty"><h2>${esc(title)}</h2><p>${esc(text)}</p>${btn(label,href(path),'clear')}</section>`;}
  function videoMarkup(media,id){return `<div class="journal-video-wrap"><video id="${esc(id)}" data-journal-video controls playsinline preload="metadata" poster="${esc(media.poster)}" aria-label="${esc(media.alt)}" aria-describedby="${esc(id)}-description"><source src="${esc(media.src)}" type="video/mp4">Ваш браузер не поддерживает видео. <a href="${esc(media.src)}">Открыть видеофайл</a></video><p class="journal-video-error" hidden>Видео не удалось загрузить. ${`<a href="${esc(media.src)}">Открыть файл отдельно ↗</a>`}</p></div>`;}

  function home(){const lead=published.find(a=>a.id==='choose-glass-by-sample')||published[0];return `${crumb([['Журнал']])}<section class="journal-page">${nav('/journal')}${heading('VIP GLASS / ЖУРНАЛ','Стекло в деталях.<br><em>Идеи в контексте.</em>','Полезные заметки, визуальные истории и короткие видео — чтобы перейти от впечатления к своему решению.')}${notice()}<section class="journal-feature"><a class="journal-feature-photo" href="#/journal/article/${esc(lead.id)}">${image(lead.cover,{eager:true})}<span class="journal-image-caption">AI-визуализация материала</span></a><div class="journal-feature-copy"><span class="eyebrow">В ФОКУСЕ / ВЫБОР МАТЕРИАЛА</span><h2>${esc(lead.title)}</h2><p>${esc(lead.intro)}</p><div class="journal-meta"><span>${lead.readMinutes} минуты чтения</span><span>Редакционный материал</span></div>${btn('Читать материал','#/journal/article/'+lead.id,'clear')}</div></section><section class="journal-section"><div class="journal-section-heading"><div><span class="eyebrow">ДЛЯ ВАШЕГО ПРОЕКТА</span><h2>Полезно <em>до выбора.</em></h2></div><a href="#/journal/useful" class="journal-text-link">Все материалы ${arrow}</a></div>${articleGrid(published.filter(a=>a.kind==='useful'))}</section><section class="journal-section journal-social-section"><div class="journal-section-heading"><div><span class="eyebrow">КОРОТКИЙ ФОРМАТ</span><h2>Истории <em>о стекле.</em></h2></div><a href="#/stories" class="journal-text-link">Смотреть истории ${arrow}</a></div><div class="story-preview-grid">${allStories.filter(e=>e.status==='active'&&!e.archived).map(e=>storyCard(e)).join('')}</div><div class="journal-section-links"><a href="#/stories/archive">Архив историй ${arrow}</a><a href="#/stories/highlights">Тематические подборки ${arrow}</a><a href="#/reels">Короткие видео · Reels ${arrow}</a></div></section><section class="journal-section"><div class="journal-section-heading"><div><span class="eyebrow">РЕДАКЦИОННЫЕ ПРИМЕРЫ</span><h2>Новости <em>журнала.</em></h2></div><a href="#/journal/news" class="journal-text-link">Все новости ${arrow}</a></div>${articleGrid(published.filter(a=>a.kind==='news'))}</section></section>`;}

  function articles(kind='useful',params=new URLSearchParams()){
    if(!['news','useful'].includes(kind))return null;
    const query=params.get('q')?.trim()||'',needle=cleanText(query);
    const list=published.filter(a=>a.kind===kind&&(!needle||cleanText([a.title,a.intro,a.topic,...a.tags].join(' ')).includes(needle)));
    return `${crumb([['Журнал','#/journal'],[kindLabel(kind)]])}<section class="journal-page">${nav('/journal/'+kind)}${heading('VIP GLASS / '+kindLabel(kind).toLocaleUpperCase('ru'),kind==='news'?'Темы и заметки.<br><em>Новости журнала.</em>':'Больше ясности.<br><em>До первого решения.</em>',kind==='news'?'Примеры редакционных публикаций для будущих новостей.':'Короткие материалы о подготовке проекта, выборе стекла и композиции конструкции.')}${notice(kind==='news')}<form class="journal-search" data-journal-search data-kind="${kind}" action="/journal/${kind}" method="get"><label for="journal-query">Поиск по публикациям</label><div><input id="journal-query" type="search" name="q" value="${esc(query)}" placeholder="Например, ${kind==='news'?'детали':'душевая'}"><button class="btn primary" type="submit">Найти ${arrow}</button>${query?'<a class="journal-search-reset" href="#/journal/'+kind+'">Сбросить</a>':''}</div></form><p class="journal-result-count" role="status">${list.length} ${list.length===1?'публикация':list.length>1&&list.length<5?'публикации':'публикаций'}${query?' по запросу «'+esc(query)+'»':''}</p>${list.length?articleGrid(list):empty('Ничего не нашлось','Попробуйте другое слово или вернитесь ко всем публикациям.','/journal/'+kind,'Все публикации')}</section>`;
  }

  function article(id){const a=published.find(x=>x.id===id);if(!a)return null;const more=published.filter(x=>x.id!==id&&x.kind===a.kind).slice(0,2);return `${crumb([['Журнал','#/journal'],[kindLabel(a.kind),'#/journal/'+a.kind],[a.title]])}<article class="journal-page journal-article"><a class="journal-back" href="#/journal/${a.kind}">← ${kindLabel(a.kind)}</a><header class="journal-article-heading"><div class="journal-meta"><span>${esc(a.topic)}</span><time datetime="${esc(a.publishDate)}">${date(a.publishDate)}</time><span>${a.readMinutes} мин чтения</span></div><h1>${esc(a.title)}</h1><p>${esc(a.intro)}</p>${a.demo?notice(a.kind==='news'):''}</header><figure class="journal-article-cover">${image(a.cover,{eager:true})}<figcaption>${esc(a.cover.credit)} · иллюстрация темы публикации</figcaption></figure><div class="journal-reading-layout"><aside class="journal-contents"><span class="eyebrow">В ЭТОМ МАТЕРИАЛЕ</span><nav aria-label="Содержание статьи">${a.sections.map((s,i)=>`<a href="#journal-part-${i+1}" data-journal-scroll="journal-part-${i+1}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.heading)}</a>`).join('')}</nav></aside><div class="journal-prose">${a.sections.map((s,i)=>`<section id="journal-part-${i+1}" tabindex="-1"><h2>${esc(s.heading)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}${a.checklist?.length?`<aside class="journal-checklist"><span class="eyebrow">СОХРАНИТЕ ДЛЯ СЕБЯ</span><h2>Перед следующим шагом</h2><ul>${a.checklist.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></aside>`:''}</div></div>${related(a)}${more.length?`<section class="journal-section"><div class="journal-section-heading"><h2>Продолжить <em>чтение.</em></h2></div>${articleGrid(more)}</section>`:''}</article>`;}

  function stories(mode='active'){
    mode=['active','archive','highlights'].includes(mode)?mode:'active';
    const title=mode==='archive'?'Истории, которые<br><em>остались с нами.</em>':mode==='highlights'?'Собрано<br><em>по смыслу.</em>':'Один кадр.<br><em>Одна мысль.</em>';
    const intro=mode==='archive'?'Сохранённые иллюстративные заметки о пространстве, материале и деталях.':mode==='highlights'?'Тематические подборки объединяют активные и архивные истории.':'Короткие заметки о стекле — от общего впечатления до отдельной детали.';
    const list=allStories.filter(e=>mode==='archive'?e.archived||e.status==='archived':e.status==='active'&&!e.archived);
    const collections=highlightCollections.map(c=>{const entries=c.storyIds.map(id=>allStories.find(e=>e.id===id)).filter(Boolean);return `<section class="story-collection" id="highlight-${esc(c.id)}"><header><img src="${esc(c.cover)}" alt="" loading="lazy" width="80" height="80"><div><span class="eyebrow">ПОДБОРКА · ${entries.length} ИСТОРИИ</span><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p></div></header><div class="story-preview-grid">${entries.map(e=>storyCard(e,{collection:c.id})).join('')}</div></section>`;}).join('');
    return `${crumb([['Журнал','#/journal'],['Истории',mode==='active'?null:'#/stories'],...(mode==='active'?[]:[[mode==='archive'?'Архив':'Подборки']])])}<section class="journal-page">${nav('/stories')}${heading('VIP GLASS / ИСТОРИИ',title,intro)}${storyTabs(mode)}${notice()}${mode==='highlights'?collections:list.length?`<div class="story-grid">${list.map(e=>storyCard(e)).join('')}</div>`:empty('Пока нет историй','Посмотрите сохранённые публикации или тематические подборки.','/stories/highlights','Открыть подборки')}</section>`;
  }

  function story(id,params=new URLSearchParams()){
    const entry=allStories.find(e=>e.id===id);if(!entry)return null;
    const requestedCollection=highlightCollections.find(c=>c.id===params.get('collection')&&c.storyIds.includes(id));
    const list=requestedCollection?requestedCollection.storyIds.map(sid=>allStories.find(e=>e.id===sid)).filter(Boolean):allStories.filter(e=>entry.archived?e.archived:e.status==='active'&&!e.archived);
    const index=list.findIndex(e=>e.id===id),previous=list[index-1],next=list[index+1];
    const route=e=>'#/stories/'+e.id+(requestedCollection?'?collection='+encodeURIComponent(requestedCollection.id):'');
    const backPath=requestedCollection?'/stories/highlights':entry.archived?'/stories/archive':'/stories';
    const context=requestedCollection?requestedCollection.title:entry.archived?'Архив историй':'Активные истории';
    return `${crumb([['Журнал','#/journal'],['Истории','#/stories'],[entry.title]])}<section class="story-viewer-page" data-story-viewer aria-label="Просмотр истории"><div class="story-viewer-top"><a class="journal-back" href="${href(backPath)}">← ${esc(context)}</a><span>${index+1} / ${list.length}</span><a href="${href(backPath)}" aria-label="Закрыть историю" class="story-close">×</a></div><div class="story-viewer-layout"><div class="story-viewer-frame ${entry.media.type==='video'?'has-video':''}"><nav class="story-progress" aria-label="Истории в подборке">${list.map((e,i)=>`<a href="${route(e)}" class="${i<=index?'is-seen':''}" ${i===index?'aria-current="step"':''} aria-label="История ${i+1}: ${esc(e.title)}"><span></span></a>`).join('')}</nav><div class="story-viewer-media">${entry.media.type==='video'?videoMarkup(entry.media,'story-video'):image(entry.media,{eager:true})}</div><div class="story-viewer-label"><span>${esc(entry.topic)}</span>${demoBadge(entry.archived?'Демо · архив':'Демо')}</div>${entry.media.type==='image'?`<div class="story-viewer-title"><span class="eyebrow">${esc(entry.media.credit)}</span><h1>${esc(entry.title)}</h1></div>`:''}</div><div class="story-viewer-copy">${entry.media.type==='video'?'<span class="eyebrow">ИЛЛЮСТРАТИВНЫЙ РОЛИК · БЕЗ ЗВУКА</span>':'<span class="eyebrow">КОРОТКАЯ ЗАМЕТКА</span>'}<h${entry.media.type==='video'?'1':'2'}>${esc(entry.title)}</h${entry.media.type==='video'?'1':'2'}><p>${esc(entry.intro)}</p><p class="story-media-description" ${entry.media.type==='video'?'id="story-video-description"':''}>${entry.media.type==='video'?'Демонстрационное видео без звуковой дорожки. Включите воспроизведение кнопкой плеера.':'AI-визуализация. Это иллюстрация идеи, не фотография выполненного проекта.'}</p><time datetime="${esc(entry.publishDate)}">${date(entry.publishDate)} · ${entry.archived?'архивная':'активная'} история</time>${entry.related?btn(esc(entry.related.label),href(entry.related.path),'clear'):''}<nav class="story-navigation" aria-label="Переключение историй">${previous?`<a href="${route(previous)}" data-story-prev rel="prev">← Предыдущая</a>`:'<span aria-disabled="true">← Предыдущая</span>'}${next?`<a href="${route(next)}" data-story-next rel="next">Следующая →</a>`:`<a href="${href(backPath)}">К ${requestedCollection?'подборкам':'историям'} →</a>`}</nav><p class="story-keyboard-hint">Листайте кнопками. Истории не переключаются автоматически.</p></div></div></section>`;
  }

  function reelCard(entry){return `<a class="reel-card" href="#/reels/${esc(entry.id)}"><div class="reel-card-image">${image(entry.media)}${demoBadge('Демо · видео')}<span class="reel-open-mark" aria-hidden="true">↗</span><div class="reel-card-caption"><span>${esc(entry.topic)}</span><h2>${esc(entry.title)}</h2><span class="reel-card-action">Открыть видео ${arrow}</span></div></div><p>Иллюстративный ролик · без звука</p></a>`;}
  function reels(){return `${crumb([['Журнал','#/journal'],['Reels']])}<section class="journal-page">${nav('/reels')}${heading('VIP GLASS / REELS','Материал.<br><em>В коротком формате.</em>','Иллюстративные видео о стекле и деталях. Откройте ролик и управляйте воспроизведением в своём темпе.')}${notice()}<div class="reel-grid">${allReels.map(reelCard).join('')}</div><aside class="journal-format-note"><span class="eyebrow">ЕЩЁ ОДИН ВЗГЛЯД</span><h2>Иногда достаточно <em>одного кадра.</em></h2><p>В историях — фотографии-иллюстрации, короткие заметки и тематические подборки.</p>${btn('Смотреть истории','#/stories','clear')}</aside></section>`;}
  function reel(id){const entry=allReels.find(e=>e.id===id);if(!entry)return null;return `${crumb([['Журнал','#/journal'],['Reels','#/reels'],[entry.title]])}<section class="journal-page reel-detail"><a class="journal-back" href="#/reels">← Все Reels</a><div class="reel-detail-layout"><figure class="reel-player">${videoMarkup(entry.media,'reel-video')}<figcaption id="reel-video-description">Демонстрационный видеомонтаж · без звука</figcaption></figure><div class="reel-detail-copy"><span class="eyebrow">VIP GLASS / REELS</span>${demoBadge('Иллюстративное видео')}<h1>${esc(entry.title)}</h1><p>${esc(entry.intro)}</p><time datetime="${esc(entry.publishDate)}">${date(entry.publishDate)}</time><div class="reel-description"><h2>О ролике</h2><p>${esc(entry.description)}</p></div>${entry.related?btn(esc(entry.related.label),href(entry.related.path),'clear'):''}<a href="${esc(entry.media.src)}" class="journal-text-link" target="_blank" rel="noopener">Открыть видеофайл ${arrow}</a></div></div></section>`;}
  function homepage(){return `<section class="section journal-homepage"><div class="journal-section-heading"><div><span class="eyebrow">ЖУРНАЛ VIP GLASS</span><h2>Чуть ближе<br><em>к своей идее.</em></h2></div><a href="#/journal" class="journal-text-link">Весь журнал ${arrow}</a></div>${articleGrid(published.filter(a=>a.kind==='useful').slice(0,3))}<div class="journal-home-social"><div><span class="eyebrow">КОРОТКИЕ ФОРМАТЫ</span><h3>Истории и видео</h3><p>Иллюстрации, заметки и детали, к которым хочется вернуться.</p></div><div class="journal-home-story-list">${allStories.filter(e=>e.status==='active'&&!e.archived).map(e=>`<a href="#/stories/${e.id}"><span>${image(e.media)}</span><strong>${esc(e.title)}</strong></a>`).join('')}</div><div class="journal-home-social-links"><a href="#/stories">Истории ${arrow}</a><a href="#/reels">Reels ${arrow}</a></div></div><p class="journal-home-demo">Демонстрационные редакционные материалы · изображения AI · иллюстративное видео</p></section>`;}

  const boundRoots=new WeakMap();
  function bind(root=globalThis.document,{navigate}={}){
    if(!root?.addEventListener)return;
    boundRoots.get(root)?.abort();const controller=new AbortController();boundRoots.set(root,controller);const signal=controller.signal;
    root.addEventListener('submit',event=>{const form=event.target.closest?.('[data-journal-search]');if(!form)return;event.preventDefault();const q=new FormData(form).get('q')?.toString().trim()||'';const path='/journal/'+form.dataset.kind+(q?'?q='+encodeURIComponent(q):'');if(navigate)navigate(path);else location.hash='#'+path;},{signal});
    root.addEventListener('click',event=>{const anchor=event.target.closest?.('[data-journal-scroll]');if(!anchor)return;event.preventDefault();const section=root.querySelector('#'+anchor.dataset.journalScroll);section?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});section?.focus({preventScroll:true});},{signal});
    root.addEventListener('keydown',event=>{const viewer=root.querySelector('[data-story-viewer]');if(!viewer||!['ArrowLeft','ArrowRight'].includes(event.key)||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey||event.target.closest?.('input,textarea,select,video,button,a,[contenteditable="true"]'))return;const target=viewer.querySelector(event.key==='ArrowLeft'?'[data-story-prev]':'[data-story-next]');if(target){event.preventDefault();target.click();}},{signal});
    root.querySelectorAll('[data-journal-video]').forEach(el=>{const showError=()=>{const note=el.parentElement.querySelector('.journal-video-error');if(note)note.hidden=false;};el.addEventListener('error',showError,{signal});el.querySelector('source')?.addEventListener('error',showError,{signal});if(el.error)showError();});
    return ()=>controller.abort();
  }
  return {home,articles,article,stories,story,reels,reel,homepage,bind};
}
